/* Tiempos y cifras que el motor escribe en español */
const tH = (s) => String(s).replace(/(\d),(\d)/g, '$1.$2').replace(/ días\b/g, ' days');
const I18N_T = '(—|\\d+(?:[.,]\\d+)? (?:h|min|días|days))';
const reT = (src) => new RegExp('^' + src.replace(/§T/g, I18N_T) + '$');
const plEn = (n, s, p) => `${n} ${+n === 1 ? s : p}`;
const LVL_EN = { Ninguno: 'None', Bajo: 'Low', Medio: 'Medium', Alto: 'High', 'Crítico': 'Critical' };
const EN_RE = [
  // Conteos
  [/^(\d+) NC mayor(?:es)? · (\d+) NC menor(?:es)?$/, (m, a, b) => `${plEn(a, 'major NC', 'major NCs')} · ${plEn(b, 'minor NC', 'minor NCs')}`],
  [/^(\d+) NC mayor(?:es)?$/, (m, a) => plEn(a, 'major NC', 'major NCs')],
  [/^(\d+) incidencias? de dependencias$/, (m, a) => plEn(a, 'dependency issue', 'dependency issues')],
  [/^(\d+) incidencias?$/, (m, a) => plEn(a, 'issue', 'issues')],
  [/^(.+) · (\d+) incidencias?$/, (m, a, b) => `${a} · ${plEn(b, 'issue', 'issues')}`],
  [/^(\d+) funci(?:ón|ones) fuera del RTO$/, (m, a) => plEn(a, 'function outside the RTO', 'functions outside the RTO')],
  [/^(\d+) de (\d+) funciones vuelven a tiempo$/, '$1 of $2 functions are back on time'],
  [/^Reloj de recuperación: (\d+) de (\d+) funciones vuelven dentro de su RTO$/, 'Recovery clock: $1 of $2 functions are back within their RTO'],
  [/^Reloj de recuperación de (.+)$/, 'Recovery clock for $1'],
  [/^([\d.,]+ %) de las funciones vuelven a tiempo$/, '$1 of functions are back on time'],
  [/^([\d.,]+ %) de RTO alcanzables$/, '$1 of RTOs achievable'],
  [/^(\d+) de (\d+)$/, '$1 of $2'],
  [/^(\d+) reglas$/, '$1 rules'],
  [/^(\d+) menor(?:es)? · (\d+) observaci(?:ón|ones) · (.+)$/, (m, a, b, c) => `${a} minor · ${plEn(b, 'observation', 'observations')} · ${c.replace(/^última prueba /, 'last test ').replace(/^sin pruebas$/, 'no tests')}`],
  [/^(\d+) \(típico\)$/, '$1 (typical)'],
  [/^Cada (\d+) días como máximo$/, 'At least every $1 days'],
  [/^Cerrar (\d+) casos?$/, (m, a) => `Close ${plEn(a, 'case', 'cases')}`],
  [/^Copia restaurada: (\d+) proyectos?$/, (m, a) => `Backup restored: ${plEn(a, 'project', 'projects')}`],
  [/^Exigida en (.+)$/, (m, a) => `Required in ${EN[a] || a}`],
  [/^(.+) ·$/, (m, a) => `${tr(a)} ·`],
  // Vistas y gráficas
  [reT('(\\d+)\\. (.+): de §T a §T · lo necesitan antes de §T'), (m, n, a, b, c, d) => `${n}. ${a}: from ${tH(b)} to ${tH(c)} · needed by ${tH(d)}`],
  [reT('(\\d+)\\. (.+): de §T a §T'), (m, n, a, b, c) => `${n}. ${a}: from ${tH(b)} to ${tH(c)}`],
  [reT('(.+): vuelve a las §T · RTO §T · MTPD §T'), (m, a, b, c, d) => `${a}: back at ${tH(b)} · RTO ${tH(c)} · MTPD ${tH(d)}`],
  [reT('(.+): vuelve a las §T · RTO §T'), (m, a, b, c) => `${a}: back at ${tH(b)} · RTO ${tH(c)}`],
  [reT('RTO §T · vuelve §T'), (m, a, b) => `RTO ${tH(a)} · back at ${tH(b)}`],
  [reT('([A-Z]-\\d+) necesita ([A-Z]-\\d+): listo a las §T'), (m, a, b, c) => `${a} needs ${b}: ready at ${tH(c)}`],
  [/^([A-Z]-\d+) necesita ([A-Z]-\d+)$/, '$1 needs $2'],
  [/^([A-Z]-\d+) depende de (.+)$/, '$1 depends on $2'],
  [reT('(Hot standby|Warm standby|Cold standby|Cloud DR|Sin estrategia) · listo a las §T'), (m, a, b) => `${a === 'Sin estrategia' ? 'No strategy' : a} · ready at ${tH(b)}`],
  [reT('Proveedor · §T'), (m, a) => `Supplier · ${tH(a)}`],
  [/^Impacto: (.+)$/, (m, a) => 'Impact: ' + a.replace(/7 días/g, '7 days').replace(/Ninguno|Bajo|Medio|Alto|Crítico/g, (w) => LVL_EN[w])],
  [/^(Operativo|Legal y regulatorio|Reputación|Personas) a (.+)$/, (m, a, b) => `${EN[a]} at ${tH(b)}`],
  [/^(.+)\. Lo necesitan (.+); la más exigente pide (.+)\.$/, (m, a, b, c) => `${EN[a] || a}. Needed by ${b}; the tightest asks for ${tH(c)}.`],
  [/^(.+)\. Lo necesitan ninguna función\.$/, (m, a) => `${EN[a] || a}. No function needs it.`],
  [reT('El RTO más exigente de una función crítica es §T\\. El plan se activaría con el objetivo ya incumplido\\.'), (m, a) => `The tightest RTO of a critical function is ${tH(a)}. The plan would activate with the objective already missed.`],
  [reT('El RTO más exigente de una función crítica es §T\\. El plan se activa §T antes\\.'), (m, a, b) => `The tightest RTO of a critical function is ${tH(a)}. The plan activates ${tH(b)} earlier.`],
  [reT('El RTO más exigente de una función crítica es §T\\. Falta el umbral de activación\\.'), (m, a) => `The tightest RTO of a critical function is ${tH(a)}. The activation threshold is missing.`],
  [/^(.+) Si la organización no está sujeta al ENS, elige la categoría que mejor refleje su exigencia\.$/, (m, a) => `${tr(a)} If the organisation is not subject to the ENS, choose the category that best reflects its requirements.`],
  [/^Se exige el análisis de impacto \(op\.cont\.1\)\.$/, 'The impact analysis is required (op.cont.1).'],
  [/^Se exigen el análisis de impacto, el plan de continuidad y las pruebas periódicas \(op\.cont\.1 a op\.cont\.3\)\.$/, 'The impact analysis, the continuity plan and periodic testing are required (op.cont.1 to op.cont.3).'],
  [/^Se exigen además medios alternativos \(op\.cont\.4\): sitio de recuperación o procedimientos manuales probados\.$/, 'Alternative means are also required (op.cont.4): a recovery site or tested manual procedures.'],
  [/^Análisis de impacto \(BIA\), plan de continuidad \(BCP\) y recuperación ante desastres \(DRP\) en un mismo modelo\. KAIROS recorre la cadena de dependencias para calcular cuándo vuelve cada función, compara el RPO con las copias reales y revisa el plan con (\d+) reglas de ISO 22301 y del ENS\.$/, 'Business impact analysis (BIA), business continuity plan (BCP) and disaster recovery (DRP) in a single model. KAIROS follows the dependency chain to calculate when each function is back, compares the RPO with the real backups and reviews the plan with $1 ISO 22301 and ENS rules.'],
  [/^(\d+) reglas revisan la coherencia del análisis de impacto, el plan y las pruebas\. Prepara la auditoría; no la sustituye\.$/, '$1 rules check the consistency of the impact analysis, the plan and the tests. It prepares the audit; it does not replace it.'],
  [/^Se muestran las (\d+) funciones con el RTO más exigente de (\d+)\.$/, 'Showing the $1 functions with the tightest RTO out of $2.'],
  [/^Continuar con (.+)$/, 'Continue with $1'],
  [/^Restauración de (.+)$/, 'Restore of $1'],
  [/^Ejercicio sobre (.+)$/, 'Exercise on $1'],
  [/^Copia de (.+)$/, 'Backup of $1'],
  [/^Eliminar (.+)$/, 'Delete $1'],
  [/^Abrir (.+)$/, 'Open $1'],
  [/^(.+) · guarda datos$/, (m, a) => `${EN[a] || a} · holds data`],
  [/^(.+) · caso de ejemplo$/, '$1 · sample case'],
  [/^(T-\d+) · (.+?) · (.+)$/, (m, a, b, c) => `${a} · ${EN[b] || b} · ${c === 'sin fecha' ? 'no date' : c}`],
  // Avisos con datos
  [/^Tema: (sistema|claro|oscuro)$/, (m, a) => `Theme: ${{ sistema: 'system', claro: 'light', oscuro: 'dark' }[a]}`],
  [/^Descargado: (.+)$/, 'Downloaded: $1'],
  [/^Caso de ejemplo: (.+)$/, 'Sample case: $1'],
  [/^(.+) demasiado grande \(máximo (\d+) MB\)$/, (m, a, b) => `${a.replace(/^El fichero es$/, 'The file is')} too large (maximum ${b} MB)`],
  [/^Activo (.+) eliminado$/, 'Asset $1 deleted'],
  [/^Función (.+) eliminada$/, 'Function $1 deleted'],
  [/^Prueba (.+) eliminada$/, 'Test $1 deleted'],
  // Detalle de las incidencias (motor)
  [/^Criticidad (ALTA|MEDIA|BAJA) sin (.+)\.$/, (m, a, b) => `${{ ALTA: 'High', MEDIA: 'Medium', BAJA: 'Low' }[a]} criticality without ${b}.`],
  [reT('RTO §T frente a un MTPD de §T: la función se recupera cuando el daño ya es inaceptable\\.'), (m, a, b) => `RTO ${tH(a)} against an MTPD of ${tH(b)}: the function recovers once the damage is already unacceptable.`],
  [reT('MTPD declarado §T; la matriz de impacto alcanza «Crítico» a las §T\\.'), (m, a, b) => `Declared MTPD ${tH(a)}; the impact matrix reaches “Critical” at ${tH(b)}.`],
  [reT('Bajar el MTPD a §T o revisar la valoración del impacto\\.'), (m, a) => `Lower the MTPD to ${tH(a)} or review the impact assessment.`],
  [reT('Depende de (.+), con RTO §T, mayor que su propio RTO de §T\\.'), (m, a, b, c) => `Depends on ${a}, with an RTO of ${tH(b)}, longer than its own RTO of ${tH(c)}.`],
  [reT('Alinear el RTO de (.+) a §T como máximo o eliminar la dependencia\\.'), (m, a, b) => `Bring the RTO of ${a} down to ${tH(b)} at most or remove the dependency.`],
  [/^El proveedor (.+) no tiene plazo de restablecimiento acordado\.$/, 'Supplier $1 has no agreed restoration time.'],
  [reT('(.+) se compromete a §T; la función necesita §T\\.'), (m, a, b, c) => `${a} commits to ${tH(b)}; the function needs ${tH(c)}.`],
  [reT('RTO objetivo §T; con las estrategias actuales la función vuelve a las §T\\. Marca el ritmo (.+?)\\.(?: Exposición: ([\\d.]+) € por incidente\\.)?'), (m, a, b, c, d) => `Target RTO ${tH(a)}; with the current strategies the function is back at ${tH(b)}. The pace is set by ${c.replace(/^el activo /, 'asset ').replace(/^el proveedor /, 'supplier ').replace(/^la función /, 'function ')}.${d ? ` Exposure: ${d.replace(/\./g, ',')} € per incident.` : ''}`],
  [reT('RPO objetivo §T; (.+) guarda datos de la función y no tiene copia definida\\.'), (m, a, b) => `Target RPO ${tH(a)}; ${b} holds the function’s data and has no backup defined.`],
  [reT('Definir la copia de (.+) con una frecuencia de §T como máximo\\.'), (m, a, b) => `Define the backup of ${a} with a frequency of ${tH(b)} at most.`],
  [reT('RPO objetivo §T; la copia de (.+) se hace cada §T\\.'), (m, a, b, c) => `Target RPO ${tH(a)}; ${b} is backed up every ${tH(c)}.`],
  [reT('Aumentar la frecuencia de copia o replicar (.+) para que la pérdida máxima no supere §T\\.'), (m, a, b) => `Increase the backup frequency or replicate ${a} so the maximum loss does not exceed ${tH(b)}.`],
  [/^Sostiene la función crítica (.+) y no se ha verificado su plan de continuidad\.$/, 'Supports critical function $1 and its continuity plan has not been verified.'],
  [/^Sostiene (.+) y no tiene estrategia de recuperación\.$/, 'Supports $1 and has no recovery strategy.'],
  [/^Falta (.+)\.$/, (m, a) => `Missing ${a.replace('el paso a paso', 'the step-by-step procedure').replace('el criterio de éxito', 'the success criterion').replace(' y ', ' and ')}.`],
  [/^Restaurar una muestra y registrar fecha, responsable y resultado \(al menos cada (\d+) días\)\.$/, 'Restore a sample and record date, owner and result (at least every $1 days).'],
  [/^Última restauración el (.+), hace (\d+) días \(límite: (\d+)\)\.$/, 'Last restore on $1, $2 days ago (limit: $3).'],
  [/^(.+) no tiene suplente: si no está disponible, el plan se detiene\.$/, '$1 has no deputy: if unavailable, the plan stops.'],
  [reT('El plan se activa a las §T y la función crítica más exigente tiene un RTO de §T: se activaría con el objetivo ya incumplido\\.'), (m, a, b) => `The plan activates at ${tH(a)} and the tightest critical function has an RTO of ${tH(b)}: it would activate with the objective already missed.`],
  [reT('Bajar el umbral de activación por debajo de §T\\.'), (m, a) => `Lower the activation threshold below ${tH(a)}.`],
  [reT('Activar el sitio alternativo lleva §T; la función crítica más exigente necesita §T\\.'), (m, a, b) => `Activating the alternate site takes ${tH(a)}; the tightest critical function needs ${tH(b)}.`],
  [/^(RTO|RPO) medido (.+)$/, (m, a, b) => `Measured ${a} ` + tH(b).replace(/ frente a /g, ' against ').replace(/; RPO medido /, '; measured RPO ').replace(/\. Sin acción correctiva\.$/, '. No corrective action.').replace(/\. Acción en curso: /, '. Action in progress: ')],
  [/^Resultado «(.+)» sin acción correctiva asignada\.$/, (m, a) => `Result “${EN[a] || a}” without an assigned corrective action.`],
  [/^La última prueba es del (.+)\.$/, 'The last test is from $1.'],
  [/^La revisión programada para el (.+) está vencida\.$/, 'The review scheduled for $1 is overdue.']
];

function tr(s) {
  if (s == null || lang() !== 'en') return s;
  const raw = String(s); const key = raw.trim();
  if (!key) return raw;
  if (Object.prototype.hasOwnProperty.call(EN, key)) { const i = raw.indexOf(key); return raw.slice(0, i) + EN[key] + raw.slice(i + key.length); }
  for (const [re, rep] of EN_RE) if (re.test(key)) { const at = raw.indexOf(key); return raw.slice(0, at) + key.replace(re, rep) + raw.slice(at + key.length); }
  return raw;
}
function translateDom(root) {
  if (!root || lang() !== 'en') return;
  const blocked = new Set();
  root.querySelectorAll('script, style, textarea, .no-tr').forEach((el) => { blocked.add(el); el.querySelectorAll('*').forEach((n) => blocked.add(n)); });
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT); const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const n of nodes) { if (n.parentElement && blocked.has(n.parentElement)) continue; const next = tr(n.nodeValue); if (next !== n.nodeValue) n.nodeValue = next; }
  root.querySelectorAll('[placeholder], [aria-label], [title]').forEach((el) => {
    if (el.closest('script, style, .no-tr')) return;
    for (const attr of ['placeholder', 'aria-label', 'title']) { if (!el.hasAttribute(attr)) continue; const next = tr(el.getAttribute(attr)); if (next !== el.getAttribute(attr)) el.setAttribute(attr, next); }
  });
}
function localize() {
  document.documentElement.lang = lang();
  if (lang() !== 'en') return;
  for (const id of ['top', 'view', 'palette', 'toast', 'tabbar']) { const el = document.getElementById(id); if (el) translateDom(el); }
}
